t.script:
function checkStrength(pw) {
  var sf = document.getElementById('sf');
  var st = document.getElementById('st');
  var score = 0;
  if (pw.length >= 6) score++;
  if (pw.length >= 10) score++;
  if (/[A-Z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  var colors = ['#dc2626','#f97316','#eab308','#16a34a','#16a34a'];
  var labels = ['Too short','Weak','Fair','Good','Strong'];
  var widths = ['20%','40%','60%','80%','100%'];
  var i = Math.min(score, 4);
  sf.style.width = pw.length ? widths[i] : '0%';
  sf.style.background = colors[i];
  st.textContent = pw.length ? labels[i] : 'Enter a password';
}

function updateLabel(input) {
  var label = document.getElementById('fileLabel');
  if (input.files.length === 0) {
    label.textContent = 'No files selected';
  } else if (input.files.length === 1) {
    label.textContent = input.files[0].name;
  } else {
    label.textContent = input.files.length + ' files selected';
  }
}
